IMAGE_CUES = ("figure", "shown in", "image", "photograph", "ecg as seen", "as shown")


def load_dx_cases(text_only: bool = True) -> list[dict]:
    """Diagnosis-cue cases. text_only=True drops image-dependent cases (Figure
    A / ECG image / photograph) that a text-only pipeline cannot answer, and
    de-duplicates identical questions."""
    cases = []
    seen = set()
    with TSV.open(encoding="utf-8") as f:
        for row in csv.DictReader(f, delimiter="\t"):
            try:
                opts = ast.literal_eval(row["options"])
            except Exception:
                opts = {}
            q = row["question"].strip()
            if not opts:
                continue
            if not any(cue in q.lower() for cue in DIAGNOSIS_CUES):
                continue
            if text_only and any(c in q.lower() for c in IMAGE_CUES):
                continue
            key = q[:120]
            if key in seen:
                continue
            seen.add(key)
            cases.append({
                "q": q, "options": opts,
                "answer_idx": row.get("answer_idx", "").strip(),
                "answer": row.get("answer", "").strip(),
            })
    return cases

