def _gather_atomic_findings(self, state: DiagnosticState) -> list[str]:
    """Atomic, KB-queryable finding phrases for the current turn.

    Mirrors the proven coverage-test harness (test_knowledge_pipeline_e2e):
    the LR cache / marker index are keyed by SHORT symptom phrases, so we
    must query clean atomic findings (e.g. 'basophilia', 'splenomegaly'),
    NOT the concatenated free-text blob (discriminator question + summary +
    vignette) whose token-overlap score is diluted to ~0 against short keys.

    Sources: (1) the matched HPO phenotypes accumulated on the state, plus
    (2) a fresh phenotype match of this turn's evidence text + vignette.
    Returns [] when nothing maps (caller logs it as a coverage gap).
    """
    findings: list[str] = []
    seen: set[str] = set()

    def _add(term: str) -> None:
        t = (term or "").strip()
        key = t.lower()
        if t and key not in seen:
            seen.add(key)
            findings.append(t)

    for p in sorted(getattr(state, "seen_evidence_phenotypes", set()) or []):
        _add(p)

    if self._knowledge_retriever is not None:
        texts: list[str] = []
        for a in state.actions_taken[-2:]:
            if isinstance(a, dict):
                if a.get("content"):
                    texts.append(a["content"])
                if a.get("result_summary"):
                    texts.append(a["result_summary"])
        if self._in_static_qa_mode() and hasattr(self.env, "get_case_summary"):
            try:
                cs = self.env.get_case_summary()
                if cs:
                    texts.append(str(cs))
            except Exception:
                pass
        if texts:
            try:
                matches = self._knowledge_retriever.match_evidence_to_phenotypes(
                    texts, threshold=0.4
                )
