def _partition(entry: dict, split: bool) -> list[dict]:
    """Return the effective L1 domain partition. When ``split`` is True, a
    domain carrying ``split_variants`` is REPLACED by its variants (§26.5(4):
    separate sub-families whose key-finding LR direction opposes the parent,
    e.g. chronic-phase MPN vs blast-bearing — “35% blasts” is FOR one and
    AGAINST the other, so they must not share a node). When False, the
    original lumped domain is used (legacy)."""
    out: list[dict] = []
    for dom in entry.get("domains", []):
        variants = dom.get("split_variants") if split else None
        if variants:
            out.extend(variants)
        else:
            out.append(dom)
    return out

