def matrix_of(base):
    m = re.match(r'medbullets_conc_([a-z0-9]+?)(_|$)', base)
    # finer: bucket by known prefixes
    for p in ('u29','n5_rp','n5','rq_mg_cc','rq_mg','rq_cc','nrq_mg_cc','nrq_mg','nrq_cc',
              'rp_on_bk_on','rp_on_bk_off','bk_on','bk_off'):
