    """Soft family match: gold token-subset of (or superset of) a candidate."""
    gt = set(re.findall(r"[a-z0-9]+", gold.lower()))
    if not gt:
        return False
    for c in candidates:
        ct = set(re.findall(r"[a-z0-9]+", str(c).lower()))
        if gt and (gt <= ct or ct <= gt):
            return True
    return False

