    """Append useful DDx chunks sharing ``source_id`` with any hit (article closure)."""
    useful = frozenset({"differential", "red_flag", "evaluation", "recommendation", "diagnostic"})
    source_ids = {h.get("source_id") for h in hits if h.get("source_id")}
    if not source_ids or not self._metadata:
        return hits
