@staticmethod
def _rrf_merge(rankings: list[dict[str, float]], *, k: int = 60) -> dict[str, float]:
    """Reciprocal-rank fusion of several {item: score} rankings. Each ranking
    contributes 1/(k + rank) per item (rank is 0-based within that ranking,
    score-descending). Robust to disparate score scales across entrances —
    the syndrome spotter weight and the finding spotter weight need not be
    comparable, only their within-entrance ORDER matters (the property that
    makes the two entrances safely fusable)."""
    fused: dict[str, float] = defaultdict(float)
    for ranking in rankings:
        ordered = sorted(ranking.items(), key=lambda kv: kv[1], reverse=True)
        for rank, (item, _score) in enumerate(ordered):
            fused[item] += 1.0 / (k + rank)
    return dict(fused)

