def _json_of(txt: str) -> dict:
    """First balanced {...} object that parses (robust to models that emit
    multiple JSON blocks / prose around the answer)."""
    depth = start = 0
    for i, ch in enumerate(txt):
        if ch == "{":
            if depth == 0:
                start = i
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                try:
                    return json.loads(txt[start:i + 1])
                except Exception:
                    continue
    return {}

